import{_ as t,o as a,c as i,ai as o}from"./chunks/framework.CKB5fCPB.js";const u=JSON.parse('{"title":"Vision","description":"","frontmatter":{},"headers":[],"relativePath":"Lore/Vision.md","filePath":"Lore/Vision.md"}'),n={name:"Lore/Vision.md"};function r(s,e,l,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to “Vision”">​</a></h1><p>We think that the next-gen web will be about people running self-hosted software again, like forums back then, but with the twist that the software will be decentralized and have a unified user interface, with servers being able to communicate with each other to be able to show the same results.</p><p>This is important for the user experience as it makes a decentralized application seem like a centralized service.</p><hr><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>It seems like today&#39;s software solutions arent implementing this well enough and putting a lot of work on the user and generally seem to have a lot of friction in their flows. Friction can easily turn a user away and make it impossible to become mainstream.</p><p>In addition to that it seems like many developers prioritize &quot;theoretical perfection&quot; over practical solutions and possibly over-engineer their solution.</p><p>For example: something is being written in Rust instead of JavaScript because it is more performant, but adds so much overhead that the relative improvement is not noticeable or worth the effort to begin with.</p><hr><h1 id="our-solution" tabindex="-1">Our solution <a class="header-anchor" href="#our-solution" aria-label="Permalink to “Our solution”">​</a></h1><p>We want to keep things practical and avoid issues as mentioned in <a href="#the-problem">The problem</a>, and its working out pretty well actually, but this depends on the project and requirements of course.</p><p>Our goal is to keep self-hosting powerful but make the experience for users and admins feel simple and unified. Servers can communicate with each other and users dont need to care about technical details. A lot is automated and runs in the background.</p><p>We avoid unnecessary complexity and generally try to keep things as simple as possible. After all we want to provide software thats actually useful and not a perfect text-book example.</p>',13)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
